import type { ComponentType, ReactNode } from 'react'
import './ResearchReport.css'

type Props = { Brand: ComponentType<{ compact?: boolean }> }

function Section({ id, index, title, children }: { id: string; index: string; title: string; children: ReactNode }) {
  return <section id={id} className="paper-section"><div className="paper-section-label"><span>{index}</span><i /></div><div className="paper-section-content"><h2>{title}</h2>{children}</div></section>
}

function Figure({ number, title, caption, children }: { number: string; title: string; caption: string; children: ReactNode }) {
  return <figure className="research-figure"><div className="research-figure-heading"><span>FIGURE {number}</span><b>{title}</b></div><div className="research-figure-body">{children}</div><figcaption>{caption}</figcaption></figure>
}

