function ProtocolFlowFigure() {
  const nodes = [
    ['A', 'Capture input', 'PCAP packets grouped by TCP stream'],
    ['B', 'Identify mail protocol', 'Payload evidence; ports are supporting context'],
    ['C', 'Track cleartext negotiation', 'SMTP EHLO / IMAP capability / POP3 STLS'],
    ['D', 'Resolve encryption transition', 'Advertised → requested → accepted → TLS'],
    ['E', 'Reconstruct TLS evidence', 'Handshake fields; certificate only if visible'],
    ['F', 'Emit explicit state', 'Observed · not observed · not applicable · unknown'],
  ]
  return <div className="protocol-flow" role="list" aria-label="Protocol parsing sequence">{nodes.map(([id, title, copy]) => <div className="protocol-flow-step" role="listitem" key={id}><span>{id}</span><b>{title}</b><small>{copy}</small></div>)}</div>
}

